import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { endpoints } from '../src/endpoints.js';

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outputFile = path.join(rootDir, 'docs', 'ENDPOINTS.md');

export function generateEndpointsDoc() {
  const lines = [
    '# Endpoint Inventory & Status',
    '',
    'This file is automatically generated by `scripts/generate-endpoints-doc.mjs`.',
    '',
    '| ID | Method | Primary Path | Status | Description |',
    '| --- | --- | --- | --- | --- |'
  ];

  for (const ep of endpoints) {
    const primaryPath = ep.paths && ep.paths.length ? ep.paths[0] : '/';
    const status = 'implemented';
    lines.push(`| \`${ep.id}\` | \`${ep.method}\` | \`${primaryPath}\` | **${status.toUpperCase()}** | ${ep.description || ''} |`);
  }

  lines.push('');
  fs.mkdirSync(path.dirname(outputFile), { recursive: true });
  fs.writeFileSync(outputFile, lines.join('\n') + '\n');
  return endpoints.length;
}

const isMain = process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href;
if (isMain) {
  const count = generateEndpointsDoc();
  console.log(`Updated ${outputFile} with ${count} endpoints.`);
}
